from flask import Flask, request
import sqlite3
app = Flask(__name__)
@app.get('/users')
def users():
    name = request.args.get('name', '')
    db = sqlite3.connect('users.db')
    return str(db.execute("SELECT name FROM users WHERE name = '" + name + "'").fetchall())

